import functools

def make_counter():
    count = 0                 # enclosing scope
    def increment():
        nonlocal count        # rebind the enclosing variable, not a new local
        count += 1
        return count
    return increment

c = make_counter()
print(c(), c(), c())          # 1 2 3 (state remembered via closure)

def memoize(fn):
    cache = {}
    @functools.wraps(fn)      # preserve fn's name/docstring
    def wrapper(*args, **kwargs):
        key = (args, tuple(sorted(kwargs.items())))
        if key not in cache:
            cache[key] = fn(*args, **kwargs)
        return cache[key]
    return wrapper

@memoize
def slow_square(x):
    return x * x

print(slow_square(4), slow_square(4))  # second call is cached
